set
  title = 'Medical Nutrition Therapy II',
  goal = 'Medical Nutrition Therapy II',
  summary = 'Advanced clinical nutrition therapy, nutrition support, and complex populations. Students apply the Nutrition Care Process to deidentified and simulated cases, integrate pathophysiology with assessment and intervention, interpret trends rather than isolated values, communicate across disciplines, and justify decisions using current evidence and the patient''s goals, culture, resources, and clinical trajectory.',
